        int[] endtime = new int[n];
        for(nextDoubleArray = 0; nextDoubleArray < n; ++nextDoubleArray) endtime[nextDoubleArray] = scanner.nextInt();

        for(nextDoubleArray = 1; nextDoubleArray < endtime.length; ++nextDoubleArray){
            output(endtime);
