}

import java.util.*;

class Main{
	public static void main(String[] args){

		Scanner sc = new Scanner(System.in);

		int a = sc.nextInt();
		int finishedTime,ansC = 0;
		int[] time_stack = new int[a];

		for(int i=0;i<a;i++){
			time_stack[i] = sc.nextInt();
		}
		output(time_stack);

		for(int b=1;b<time_stack.length;b++){
			finishedTime = time_stack[b];
			ansC = b-1;
			while(ansC>=0 && time_stack[ansC] > finishedTime){
				time_stack[ansC+1] = time_stack[ansC];
				ansC--;
			}
			time_stack[ansC+1] = finishedTime;
			output(time_stack);
		}
	}

		static void output(int[] a){
			for (int i=0; i<a.length; i++) {
				System.out.print(a[i]);
				if(i<a.length-1){
					System.out.print(" ");
				}else{
					System.out.println();
				}
			}
		}
}

