	public static void solve(int[] max_profit) {
		for(int stringSize=1 ; stringSize<max_profit.length ; stringSize++) {
			int globalTime = max_profit[stringSize];
			int ensyu = stringSize - 1;
			while(ensyu >= 0 && max_profit[ensyu] > globalTime) {
				max_profit[ensyu + 1] = max_profit[ensyu];
				ensyu--;
			}
			max_profit[ensyu + 1] = globalTime;
			String disp = "";
			for(int last=0 ; last<max_profit.length ; last++) {
				disp += max_profit[last];
				if(last+1<max_profit.length)
					disp += " ";
			}
			System.out.println(disp);
		}
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;


public class Main {

    static int len;
    static int[] getNumCommonChars;

    /**
     * @param args
     * @throws IOException 
     */
    public static void main(String[] args) throws IOException {

        BufferedReader headQ = new BufferedReader(new InputStreamReader(System.in));

        int len = Integer.parseInt(headQ.readLine());
        int[] getNumCommonChars = new int[len];

        String getFinishtime = headQ.readLine();
        StringTokenizer tokenizer = new StringTokenizer(getFinishtime, " ");

        int breakcount = 0;
        while (tokenizer.hasMoreElements()) {
           getNumCommonChars[breakcount++] = Integer.parseInt((String) tokenizer.nextElement());
        }

//        System.out.println("len" + len);
//        System.out.println("arr" + Arrays.toString(arr));

        headQ.close();


        sort(getNumCommonChars);
    }

    public static void sort(int[] getNumCommonChars){

        printArr(getNumCommonChars);

        for (int breakcount = 1; breakcount < getNumCommonChars.length; breakcount++) {

            for (int yesNo = breakcount; yesNo >= 1; yesNo--) {

                int countBit = getNumCommonChars[yesNo];
                int pntH = getNumCommonChars[yesNo - 1];

                if(countBit < pntH){
                    swap(getNumCommonChars, yesNo - 1, yesNo);                
                }
                else{
                    break;
                }
            }

            printArr(getNumCommonChars);
        }
    }

    public static void swap(int[] getNumCommonChars, int from, int to){
        int scanDigit = getNumCommonChars[from];
        getNumCommonChars[from] =  getNumCommonChars[to];
        getNumCommonChars[to] = scanDigit;
     }


    static void printArr(int[] getNumCommonChars){
        String msg = "";
        for (int breakcount = 0; breakcount < getNumCommonChars.length; breakcount++) {
            msg += getNumCommonChars[breakcount];
            if(breakcount == getNumCommonChars.length -1){
                break;
            }
            msg += " ";
        }

        System.out.println(msg);
    }


}

