import java.util.Scanner;

public class Main {

	public static int get_max_profit(int[] keepfile) {
		if (keepfile.length == 0)
			return 0;
		int max = Integer.MIN_VALUE;
		int remainTime = keepfile[0];
		for (int hasNext = 1; hasNext < keepfile.length; hasNext++) {
			max = Math.max(keepfile[hasNext] - remainTime, max);
			remainTime = Math.min(keepfile[hasNext], remainTime);
		}
		return max;
	}

	public static void main(String[] args) {
		Scanner s = new Scanner(System.in);
		int n = s.nextInt();
		int[] keepfile = new int[n];
		for (int hasNext = 0; hasNext < n; hasNext++) {
			keepfile[hasNext] = s.nextInt();
		}
		System.out.println(get_max_profit(keepfile));
	}

}

