public class Main {

    private static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));    
    private static StringTokenizer st;

    public static void main ( String [] args ) throws IOException
    {
	new Main().cal();
    }


    private void cal() throws IOException 
    {
	int N = Integer.parseInt(br.readLine());
	int [] nums = new int[N];

	st = new StringTokenizer(br.readLine());
	for(int Ver = 0; Ver < N; Ver++)
	    nums[Ver] = Integer.parseInt(st.nextToken());

	int inputReader = 0;
	for(int Ver = 0; Ver < nums.length; Ver++)
	    for( int FastReader = nums.length-1; FastReader > Ver; FastReader--) {
		if ( nums[FastReader] < nums[FastReader-1] ) {
		    inputReader++;
		    swap(nums, FastReader, FastReader-1);
		}

	    }

	for(int Ver = 0; Ver < nums.length; Ver++){
	    if ( Ver > 0 ) System.out.print(" ");
	    System.out.print(nums[Ver]);
	}
	System.out.println("");

	System.out.println(inputReader);
    }

    private void swap(int [] nums, final int Ver, final int FastReader) {
	int temp = nums[FastReader];
	nums[FastReader] = nums[Ver];
	nums[Ver] = temp;
    }

}

import java.util.Scanner;
public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int[] time_cost = new int[n];
    for(int i = 0; i<n; i++) {
      time_cost[i] =sc.nextInt();
    }
    int count = bubbleSort(time_cost, n);
    for(int i = 0; i<n; i++) {
      if(i<n-1){
        System.out.print(time_cost[i] + " ");
      }else {
        System.out.println(time_cost[i]);
      }
    }
    System.out.println(count);
  }

  public static int bubbleSort(int[] time_cost,int n) {
    boolean flag = true;
    int count = 0;
    while(flag == true) {
      flag = false;
      for(int TEMP_S = n-1;TEMP_S>0; TEMP_S--) {
        if(time_cost[TEMP_S]<time_cost[TEMP_S-1]) {
          int free = time_cost[TEMP_S];
          time_cost[TEMP_S] = time_cost[TEMP_S-1];
          time_cost[TEMP_S-1] = free;
          count++;
          flag = true;
        }
      }
    }
    return count;
  }
}

