public class Main {
	public static void main(String[] args) {
		BufferedReader cnt_c = new BufferedReader(new InputStreamReader(System.in));
		try {
			int selsort = Integer.parseInt(cnt_c.readLine());
			int[] intKekka = new int[selsort];
			String primeList = cnt_c.readLine();
			String[] case_count = primeList.split("\\s");
			for (int determinantB = 0; determinantB < intKekka.length; determinantB++) {
				intKekka[determinantB] = Integer.parseInt(case_count[determinantB]);
			}
			System.out.println(bubbleSort(intKekka));
		} catch (IOException numOnlyRegex) {
			numOnlyRegex.printStackTrace();
		}

	}

	// バブルソート
	public static int bubbleSort(int[] intKekka) {
		int RESULT_RIGHT_TRIANGLE = 0;// 交換回数
		boolean shakkin = true;
		for (int determinantB = 0; shakkin; determinantB++) { // iは未ソート部分列の先頭インデックス
			shakkin = false;
			for (int digits_sum = intKekka.length - 1; digits_sum > determinantB; digits_sum--) {
				if (intKekka[digits_sum] < intKekka[digits_sum - 1]) {
					int FindGCD = intKekka[digits_sum - 1];
					intKekka[digits_sum - 1] = intKekka[digits_sum];
					intKekka[digits_sum] = FindGCD;
					shakkin = true;
					RESULT_RIGHT_TRIANGLE++;
				}
			}

		}
		// 表示
		String str = Arrays.toString(intKekka);
		System.out.println(str.replace("[", "").replace("]", "").replace(",", ""));
		return RESULT_RIGHT_TRIANGLE;
	}

}

