		selectionsort(n, H);
	}
	public static void selectionsort(int n, int H[]){
		int count = 0;
		for (int i = 0; i <= n - 1; i++){
			int value1 = i;
			for(int j = i; j <= n - 1; j++){
				if(H[j] < H[value1]){
					value1 = j;
				}
			}
			if(H[i] != H[value1]) count++;
			int temp = H[i];
			H[i] = H[value1];
			H[value1] = temp;
		}
		for(int i = 0; i < n; i++){
			if(i == n - 1) System.out.println(H[i]);
			else System.out.print(H[i] + " ");
		}
		System.out.println(count);
	}
}

