import java.util.Scanner;

class Main {public static void main(String args[]) {
		Scanner sc = new Scanner(System.in);

		Queue<String> eps = new ArrayDeque<>();
		Queue<Integer> lengthT = new ArrayDeque<>();

		int n = sc.nextInt();
		int symbol = sc.nextInt();

		for(int i = 0; i < n; i++) {
			eps.add(sc.next());
			lengthT.add(sc.nextInt());
		}

		int input = 0;
		while(!eps.isEmpty()) {
			String devide = eps.poll();
			int checkPrimeNumber = lengthT.poll();

			if(checkPrimeNumber - symbol <= 0) {
				input += checkPrimeNumber;
				System.out.println(devide + " " + input);
			}else {
				input += symbol;
				eps.add(devide);
				lengthT.add(checkPrimeNumber - symbol);
			}
		}
	}
}

