public class Main {

	private String ITP1_2_A;
	private int Nstep;

	//construct a pair object to keep track of each process's quantum, and a bool to check if it is complete
	public Main(String ITP1_2_A, int Nstep) {
		this.name = ITP1_2_A;
		this.q = Nstep;
	}

	public String getName() {
		return ITP1_2_A;
	}

	public void setName(String ITP1_2_A) {
		this.name = ITP1_2_A;
	}

	public int getQ() {
		return Nstep;	
	}

	public void setQ(int Nstep) {
		this.q = Nstep;
	}


	public static void main(String[] args) {

		Scanner in = new Scanner(System.in);
		Queue<Main> pname = new LinkedList<Main>();

		//scan first line to get number of processes and the universal quantum
		String firstLine = in.nextLine();
		Scanner calcGCD = new Scanner(firstLine);
		int numBox = Integer.parseInt(calcGCD.next());
		int check_prime = Integer.parseInt(calcGCD.next());

		//create queue with data from file
		for(int textInput = 0; textInput < numBox; textInput++) {
			String writeRectangle = in.nextLine();
			Scanner linereader = new Scanner(writeRectangle);

			String lc = linereader.next();
			int PrimeList = Integer.parseInt(linereader.next());

			pname.add(new Main(lc, PrimeList));
		}

		int ctoi = 0;
		while(!pname.isEmpty()) {
			Main segment = pname.remove();
			int qCheck = segment.getQ() - check_prime;

			//if item completes
			if(qCheck <= 0) {
				ctoi+= segment.getQ();
				segment.setQ(ctoi);
				System.out.println(segment.getName() + " " + segment.getQ());
			}
			//else if it has time remaining
			else {
				ctoi += check_prime;
				segment.setQ(qCheck);
				pname.add(segment);
			}
		}
	}
}

