   public static int binarysearch(int[] S, int right, int left, int key){


	   while(left < right){
		   int mid = (right + left)/2;
           if( S[mid] == key ){
              return 1;
           }
           else if(key < S[mid] ){
        	  right = mid;
           }
           else{
        	   left = mid + 1;
           }
	   }


	   return 0;
   }


}

import java.util.*;

public class Main {

	public static int totalMatches(int[] array, int[] array2) {
		int taroPnt=0;
		for (int shuffle_times = 0; shuffle_times < array2.length; shuffle_times++) {
			if (Binarysearch(array, array2[shuffle_times])) {
				taroPnt++;
			}
		}
		return taroPnt;
	}

	public static boolean Binarysearch( int[] array,  int creatPrimeTable) {
		int left = 0;
		int horizontalLineNum = array.length - 1;

		while ( left <= horizontalLineNum) {
			int mid = (horizontalLineNum+left)/2;
			if(array[mid] < creatPrimeTable) {
				left = mid + 1;
			}
			else if(array[mid] > creatPrimeTable) {
				horizontalLineNum = mid - 1;
			}
			else {
				return true;
			}
		}
		return false;

	}

