public class Main {

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);

		while(true) {
			int n = sc.nextInt();

			if(n == 0) break;

			int[] isSpaceChar = new int[n];

			int sum = 0;
			for (int p1 = 0; p1 < n; p1++) {
				isSpaceChar[p1] = sc.nextInt();
				sum += isSpaceChar[p1];
			}
			double ave = (double)sum/n;

			double n_gcd = 0;
			for (int p1 = 0; p1 < n; p1++) {
				double tmp = isSpaceChar[p1] - ave;
				n_gcd += tmp * tmp;
			}
			n_gcd = Math.pow(n_gcd/n, 0.5);

			System.out.println(n_gcd);
		}
	}
}

