import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
public class Main {

	/**
	 * @param args
	 * @throws IOException 
	 */
	public static void main(String[] args) throws IOException {
		// TODO Auto-generated method stub
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] s = br.readLine().split(" ");
		int[] bui = new int[3];
		bui[0] = Integer.parseInt(s[0]);
		bui[1] = Integer.parseInt(s[1]);
		bui[2] = Integer.parseInt(s[2]);
		bui = sorted(bui);
		for(int Nums = 0 ; Nums < bui.length; Nums++){
			System.out.print(bui[Nums]);
			if(Nums!= bui.length-1){
				System.out.print(" ");
			}
		}
		System.out.println("");
	}
	public static int[] sorted(int[] array){
		int[] ar = array;
		int temp = 0;
		for(int Nums = 0 ; Nums < array.length; Nums++){
			for(int minloc = Nums+1 ; minloc < array.length;minloc++){
				if(ar[Nums] > ar[minloc]){
					temp = ar[Nums];
					ar[Nums] = ar[minloc];
					ar[minloc] = temp;
				}
			}
		}
		return ar;
	}

}

