		String value[] = inputed.split("[\\s]+");
		//int intInputed = Integer.parseInt(inputed);

		int sNum  = Integer.parseInt(value[0]);
		int printHelloWorld = Integer.parseInt(value[1]);
		int YesNo  = Integer.parseInt(value[2]);

		int[] totalElapsedTime = new int[3];
		totalElapsedTime[0] = sNum;
		totalElapsedTime[1] = printHelloWorld;
		totalElapsedTime[2] = YesNo;

		totalElapsedTime = sort(totalElapsedTime, 0, 1);
		totalElapsedTime = sort(totalElapsedTime, 1, 2);
		totalElapsedTime = sort(totalElapsedTime, 0, 1);

		System.out.println(totalElapsedTime[0] + " " + totalElapsedTime[1] + " " + totalElapsedTime[2]);




	}
	public static int[] sort(int[] array, int number, int number2) {
		if (array[number] > array[number2]) {
			int pos1 = array[number];
			int pos2 = array[number2];

			array[number]  = pos2;
			array[number2] = pos1;
		}

			return array;


	}
}

