import java.io.*;
import java.util.*;
public class Main {
	public static void main(String[] args) throws IOException {
		BufferedReader prime_num = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer(prime_num.readLine(), " ", false);
		int isFullQ = Integer.parseInt(st.nextToken());
		int Gcd = Integer.parseInt(st.nextToken());
		int MAX_F = Integer.parseInt(st.nextToken());		
		prime_num.close();
		int out = 0;
		for (int time_stack = isFullQ; time_stack <= Gcd; time_stack++) {
			if (MAX_F % time_stack == 0) out++;
		}
		System.out.println(out);
	}
}

