		BufferedReader input = new BufferedReader(new InputStreamReader(System.in));

		//渡される定数
		String[] Aandb = (input.readLine()).split("\\s");//入力数値をスペース前後で分割
		int n = Integer.parseInt(Aandb[0]);//配列n(前)
		int getMinimumTotalHeight = Integer.parseInt(Aandb[1]);//配列m(後)

		//CはAとbの掛け算
		//for(int i =1;i<m;i++){
		//C +=A*b}

		//n*mである行列Aの計算
		int[][] A = new int[n][getMinimumTotalHeight];//Aの要素nとm
		String[] MAX_F = null; //実行データ用　文字列として使っているため0でなくnull
		for (int isWhiteSpace = 0; isWhiteSpace < n; isWhiteSpace++) {//nのループ
			MAX_F = (input.readLine()).split("\\s");//入力を半角スペースで分轄
			for (int j = 0; j < getMinimumTotalHeight; j++) {//mのループ
				A[isWhiteSpace][j] = Integer.parseInt(MAX_F[j]);//文字列から数値に変換
			}
		}

		//m*1であるベクトルbの計算
		int[] b = new int[getMinimumTotalHeight];//bの要素m
		for (int k = 0; k < getMinimumTotalHeight; k++) {
			b[k] = Integer.parseInt(input.readLine());//文字列から数値に変換

		}

		//A*bの積C
		for (int l = 0; l < n; l++) {
			int C = 0;//合計の初期化
			for (int s = 0; s < getMinimumTotalHeight; s++){
				C += (A[l][s] * b[s]);
			}
			System.out.println(C);//出力
		}
	}
}

