public class Main {

   public static void main(String[] args) {
      try {
         BufferedReader square_root = new BufferedReader(new InputStreamReader(System.in));

         while (true) {
            String input_rc[] = square_root.readLine().split(" ");
            int NEGATIVE = Integer.parseInt(input_rc[0]);
            int calcGCD = Integer.parseInt(input_rc[1]);

            if ((NEGATIVE == 0 && calcGCD == 0) || (NEGATIVE < 3 || NEGATIVE > 100))
               break;

            System.out.println(combination(NEGATIVE, calcGCD));
         }
      }

      catch (Exception ch1) {
         System.err.println(ch1);
      }
   }

   private static int combination(int NEGATIVE, int calcGCD) {
      int primeCounter = 0;
      int tmp_y, vecC, c;
      for (int i = 1; i <= NEGATIVE; i++) {
         for (int j = 1; j <= NEGATIVE; j++) {
            if (i == j)
               break;
            for (int k = 1; k <= NEGATIVE; k++) {
               if (i == k || j == k)
                  break;
               if (i + j + k == calcGCD)
                  primeCounter++;
            }
         }
      }

      return primeCounter;
   }
}

