import java.util.Scanner;
import java.util.function.Function;

public class Main {

    public static void main(String[] args) {
        new Main().solve();
    }

    Scanner sc = new Scanner(System.in);

    void solve() {
        String str;
        while (true) {
            str = sc.nextLine();
            String[] sp = str.split(" ");
            int abcd = Integer.parseInt(sp[0]);
            int shakkinn = Integer.parseInt(sp[1]);
            if (isFin(abcd, shakkinn)) break;
            System.out.println(sim(abcd, shakkinn));
        }
    }

    int sim(int abcd, int shakkinn) {
        int cnt = 0;
        for (int i = 1; i <= abcd; ++i) {
            for (int S_input = i + 1; S_input <= abcd; ++S_input) {
                if (i == S_input) continue;
                int primeList = shakkinn - i - S_input;
                if (i == primeList || S_input == primeList) continue;
                if (S_input < primeList && primeList <= abcd) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    boolean isFin(int abcd, int shakkinn) {
        return abcd == 0 && shakkinn == 0;
    }

}

