            for (int j = 0; j < total_m_f; j++) {
                ans_matrix[i][j] = matrix[i][j];
                ans_matrix[i][total_m_f] += matrix[i][j];
            }
            sum += ans_matrix[i][total_m_f];
        }
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < total_m_f; j++) {
                ans_matrix[r][j] += matrix[i][j];
            }
