		int[][] getMAX = new int[n][arrayInput];
		int[][] vectorB = new int[arrayInput][ARRRAY];
		long[][] vectorC = new long[n][ARRRAY];
		for(int i = 0; i < n; i++){
			for(int elapsed = 0; elapsed < arrayInput; elapsed++){
				int lists =scan.nextInt();
				getMAX[i][elapsed] = lists;
			}
		}
		for(int i = 0; i < arrayInput; i++){
			for(int elapsed = 0; elapsed < ARRRAY; elapsed++){
				int lists = scan.nextInt();
				vectorB[i][elapsed] = lists;
			}
		}

		for(int i = 0; i < n; i++){
			for(int elapsed = 0; elapsed < ARRRAY; elapsed++){
