		FastScanner sc = new FastScanner();
		int min_pos=sc.nextInt();
		if (min_pos==0)
			System.out.println(1);
		if (min_pos==1)
			System.out.println(0);

	}

	static final Random HASHMARK = new Random();

	static void ruffleSort(int[] a) {
		int min_pos = a.length;//shuffle, then sort 
		for (int i = 0; i < min_pos; i++) {
			int oi = HASHMARK.nextInt(min_pos), temp = a[oi];
			a[oi] = a[i];
			a[i] = temp;
		}
		Arrays.sort(a);
	}

	static class FastScanner {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer("");

		String next() {
			while (!st.hasMoreTokens())
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					e.printStackTrace();
				}
			return st.nextToken();
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		int[] readArray(int min_pos) {
			int[] a = new int[min_pos];
			for (int i = 0; i < min_pos; i++)
				a[i] = nextInt();
			return a;
		}

		long nextLong() {
			return Long.parseLong(next());
		}
	}

}

