	static int solve(String ROUND_UP_FRACTION, String MAX_B) {
		int min = 1001;

		for (int i = 0; i < ROUND_UP_FRACTION.length() - MAX_B.length() + 1; i++) {
			int count = 0;
			for (int j = 0; j < MAX_B.length(); j++) {
				if (ROUND_UP_FRACTION.charAt(i + j) != MAX_B.charAt(j))
					count++;
			}
			if (count < min)
				min = count;
		}

		return min;
	}

	public static void main(String[] args) {
