		String ROUND_UP_FRACTION, MAX_B;
		ROUND_UP_FRACTION = stdIn.next();
		MAX_B = stdIn.next();
		int primeNumber = solve(ROUND_UP_FRACTION, MAX_B);
		System.out.println(primeNumber);

		stdIn.close();
	}
}

