public class Main {
    public static void main(String[] args) {
        InputStream progress = System.in;
        OutputStream eq = System.out;
        InputReader in = new InputReader(progress);
        PrintWriter isPrimeNumber = new PrintWriter(eq);
        Task depth = new Task();
        depth.solve(in, isPrimeNumber);
        isPrimeNumber.close();
    }
    // main solver
    static class Task{
        public void solve(InputReader in, PrintWriter isPrimeNumber) {
            int drop = in.nextInt();
            if (drop % 1000 == 0){
                isPrimeNumber.println(0);
            }
            else{
                isPrimeNumber.println(1000 - (drop % 1000));
            }
        }
    }
    // fast input reader class;
    static class InputReader {
        BufferedReader br;
        StringTokenizer st;

        public InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                String line = null;
                try {
                    line = br.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }
        public long nextLong(){
            return Long.parseLong(nextToken());
        }
    }
}

