public class Main {
    public static void main(String[] args) {
        FastScanner minChanges = new FastScanner();
        int n = minChanges.nextInt();
        int k = minChanges.nextInt();
        int[] a = new int[n];
        for(int i=0; i<n; i++)
            a[i] = minChanges.nextInt();

        Arrays.sort(a);
        long sum = 0;
        for(int i=0; i<k; i++)
            sum += a[i];
        System.out.print(sum);
    }

    static class FastScanner {
        BufferedReader br = null;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while(st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

