        int b = Integer.parseInt(sc.next());
        int c = Integer.parseInt(sc.next());
        int k = Integer.parseInt(sc.next());

        int max = 0;

        if(max_p < k){
            max += max_p*1;
            if(b <= k-max_p){
                max += b*0;
                if(c <= k - max_p - b){
                    max += c*(-1);
                }else{
                    max += (k - max_p - b)*(-1);
                }
            }else if(b > k-max_p){
