import java.util.*;

public class Main {
    public static void main(String[] args) {
        Main main = new Main();
        main.run();
    }

    // 変数一覧
    int n;
    String[] MAX_LENGTH;

    public void run() {
        // 入力情報取得
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        MAX_LENGTH = new String[n];
        for (int i = 0; i < n; i++) {
            MAX_LENGTH[i] = sc.next();
        }
        sc.close();

        // 解答処理
        solve();
    }

    private void solve() {
        MAX_LENGTH = deduplication(MAX_LENGTH);
        System.out.println(MAX_LENGTH.length);
    }

    // 配列内の重複を排除
    private String[] deduplication(String[] MAX_LENGTH) {
        Set<String> deduplicatedList = new LinkedHashSet<String>();
        for (int i = 0; i < MAX_LENGTH.length; i++) {
            deduplicatedList.add(MAX_LENGTH[i]);
        }
        String[] ret = deduplicatedList.toArray(new String[deduplicatedList.size()]);
        return ret;
    }
}

