import java.math.BigInteger;
import java.util.*;

public class Main {

    public static void main(String[] args) throws IOException {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        InputReader.OutputWriter out = new InputReader.OutputWriter(outputStream);

        long sideLengths_Str = in.nextLong();
        long m = in.nextLong();
        if(sideLengths_Str%m == 0) {
            out.println(0);
        }
        else {
            if(sideLengths_Str < m) {
                out.println(Math.min(sideLengths_Str,m-sideLengths_Str));
            }
            else {
                long min = sideLengths_Str/m;
                out.println(Math.min(sideLengths_Str-min*m,++min*m-sideLengths_Str));
            }
        }
        out.flush();
    }
}

