public class Main {

	public static void main(String[] args) {
		Scanner input = new Scanner(System.in);
		String numberOfReceivedDataset = input.nextLine();
		int hashInt = numberOfReceivedDataset.length();
		int START = hashInt/2;
		if (Palindrome(numberOfReceivedDataset)&&Palindrome(numberOfReceivedDataset.substring(0,START))&&Palindrome(numberOfReceivedDataset.substring(START+1))) {
			System.out.println("Yes");
		}else {
			System.out.println("No");
		}
	}
	public static boolean Palindrome(String numberOfReceivedDataset) {
		for (int i = 0; i < numberOfReceivedDataset.length()/2; i++) {
			if (numberOfReceivedDataset.charAt(i)!=numberOfReceivedDataset.charAt(numberOfReceivedDataset.length()-i-1)) return false;
		}
		return true;
	}
}

