import java.io.IOException;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) throws IOException {

		Scanner scan = new Scanner(System.in);
		int swap2;
		swap2 = scan.nextInt();

		if (swap2 % 2 == 0) {
			System.out.println(swap2 / 2);
		} else {
			System.out.println(swap2 / 2 + 1);
		}

	}

	/**
	 * 余りを求める。
	 * @param a
	 * @param b
	 * @return 余り。余りがマイナスの時はプラスで返す。ｓ
	 */
	public static long myMod(long a, long b) {
		long ret = 0;

		ret = a % b;

		if (ret < 0) {
			ret += b;
		}

		return ret;
	}

	/**
	 * 乗数を求める ※mod対応
	 * @param a 基数
	 * @param n 乗数
	 * @param primeNumMod 法 mod値 使わない場合は「0」
	 * @return
	 */
	public static long myModPow(long a, long swap2, long primeNumMod) {

		long ans = 1;

		//乗数が0の場合→1
		if (swap2 == 0)
			return 1;

		if (primeNumMod == 0) {
			//modを使わないとき

			while (swap2 > 0) {

				if (swap2 % 2 == 0) {
					//累乗が偶数の時

					a *= a;
					swap2 = swap2 / 2;
				} else {
					//累乗が奇数の時
					ans *= a;
					swap2--;
				}
			}

			return ans;

		} else {
			//modを使うとき

			//初めに桁を落とす
			a = myMod(a, primeNumMod);

			while (swap2 > 0) {

				if (swap2 % 2 == 0) {
					//累乗が偶数の時

					a *= myMod(a, primeNumMod);
					swap2 = swap2 / 2;

				} else {
					//累乗が奇数の時
					ans *= myMod(a, primeNumMod);
					swap2--;

				}
			}

			return myMod(ans, primeNumMod);

		}

	}

}

