public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int[] second = new int[n];

        int minPosition = 100;
        int maxPosition = 1;
        for (int low = 0; low < n; low++) {
            int val = sc.nextInt();
            minPosition = Math.min(minPosition, val);
            maxPosition = Math.max(maxPosition, val);
            second[low] = val;
        }

        int minValue = Integer.MAX_VALUE;
        for (int p = minPosition; p <= maxPosition; p++) {
            int val = 0;
            for (int low = 0; low < n; low++) {
                val += stamina(second[low], p);
            }
            minValue = Math.min(minValue, val);
        }
        System.out.println(minValue);
    }

    private static int stamina(int bigInteger3, int meetingIndex) {
        return (int) Math.pow(bigInteger3 - meetingIndex, 2);
    }
}

