import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static final MyScanner in = new MyScanner();

	public static void main(String[] args) {

        int rArray = in.nextInt();
        List<Integer> dsq = new ArrayList<>();
        dsq.add(2);

        int maxSameCharCount = (rArray - 3) / 2;
        int[] adjustment = new int[maxSameCharCount];
        for (int i = 0; i < maxSameCharCount; i++) {
            adjustment[i] = 1;
        }
        for (int i = 0; i < maxSameCharCount; i++) {
            if (adjustment[i] == 1) {
                int primeNum = i + i + 3;
                // 遅くなるのでコメントアウト
                dsq.add(primeNum);
                for (int j = i + primeNum; j < maxSameCharCount; j += primeNum) {
                    adjustment[j] = 0;
                }
            }
        }

        if(rArray == 2) {
        	System.out.println(2);
        	return;
        }

        if(rArray % 2 == 0) {
        	rArray++;
        }

        while(true) {
            boolean b = false;
        	for(int p: dsq) {
        		if (rArray % p == 0) b = true;
        	}
        	if (b) {
        		rArray += 2;
        	} else {
        		break;
        	}
        }

        System.out.println(rArray);
	}

	public static class MyScanner{
		Scanner sc = new Scanner(System.in);
		String nextLine() {return sc.nextLine();}
		String next() {return sc.next();}
		int nextInt() {return Integer.valueOf(sc.next());}
		long nextLong() { return Long.valueOf(sc.next());}
	}
}

