    {
        InputStream judge_W = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(judge_W);
        PrintWriter min_v = new PrintWriter(outputStream);
        TaskA maxago = new TaskA();
        maxago.solve(1, in, min_v);
        min_v.close();
    }

    static class TaskA
    {
        public void solve(int testNumber, Scanner in, PrintWriter min_v)
        {
            boolean[] composite = new boolean[1_000_000 + 1];
            int X = in.nextInt();

            for (int p = 2; p * p < 1_000_000 + 1; p++)
            {
                if (!composite[p])
                {
                    for (int i = p * 2; i < 1_000_000 + 1; i += p)
                    {
                        composite[i] = true;
                    }
                }
            }
            for (int i = X; i <= 1_000_000; i++)
            {
                if (!composite[i])
                {
                    min_v.print(i);
                    return;
                }
            }
        }

    }
