        return listH / GCD(listH, DELIMITER_SPACE) * DELIMITER_SPACE;
    }

    long GCD(long listH, long DELIMITER_SPACE){
        if(DELIMITER_SPACE == 0) return listH;
        return GCD(DELIMITER_SPACE, listH%DELIMITER_SPACE);
    }

