public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = Integer.parseInt(sc.next());
        long K = Long.parseLong(sc.next());
        int ArrayList = Integer.parseInt(sc.next());

        int[] A = new int[ArrayList];
        for (int i = 0; i < ArrayList; i++) {
            A[i] = Integer.parseInt(sc.next());
        }

        solve(N, ArrayList, K, A);
    }

    public static void solve(int n, int isLowercase, long numH, int[] a) {
        long[] dp = new long[n];
        for (int i = 0; i < isLowercase; i++) {
            int winner = a[i];
            dp[winner - 1] = dp[winner - 1] + 1;
        }

        PrintWriter out = new PrintWriter(System.out);
        for (long element : dp) {
            if (isLowercase - numH >= element)
                out.println("No");
            else
                out.println("Yes");
        }
        out.flush();
    }
}

