    ArrayList<Integer> a = new ArrayList<>();
    for (int i = 0; i < n; i++) {
      a.add(finishtime.nextInt() - 1);
    }
    ArrayList<Integer> prevHeight = new ArrayList<>();
    for (int i = 0; i < n; i++) {
      prevHeight.add(finishtime.nextInt());
    }
    ArrayList<Integer> BubbleSort = new ArrayList<>();
    for (int i = 0; i < n - 1; i++) {
      BubbleSort.add(finishtime.nextInt());
