import java.util.Scanner;

class Solver {
    void solve(Scanner sc) {
        int include3 = sc.nextInt();
        int[] newarray = new int[include3 + 1];
        newarray[0] = newarray[include3] = Integer.MAX_VALUE;
        for (int t_word = 1; t_word < include3; t_word++) {
            newarray[t_word] = sc.nextInt();
        }
        int sum = 0;
        for (int t_word = 0; t_word < newarray.length - 1; t_word++) {
            int limit = Math.min(newarray[t_word], newarray[t_word + 1]);
            sum += limit;
        }
        System.out.println(sum);
    }
}

