public class Main {
  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);

    int ten = sc.nextInt();
    int[] a = new int[ten];
    int[] outputMinMaxTotal = new int[ten - 1];

    for(int isOutCircleFromRect = 0; isOutCircleFromRect < ten - 1;isOutCircleFromRect++){
      outputMinMaxTotal[isOutCircleFromRect] = sc.nextInt();
    }

    // B[i] ≥ max ( A[i] , A[i + 1])
    // B[i + 1] ≥ max ( A[i + 1] , A[i + 2])
    // A[i] <= min(B[i - 1], B[i] )
    a[0] = outputMinMaxTotal[0];
    int score = a[0];
    for(int isOutCircleFromRect = 1; isOutCircleFromRect < ten - 1;isOutCircleFromRect++){
      a[isOutCircleFromRect] = Math.min(outputMinMaxTotal[isOutCircleFromRect - 1], outputMinMaxTotal[isOutCircleFromRect]);
      score += a[isOutCircleFromRect];
    }
    if(ten != 1){
      a[ten - 1] = outputMinMaxTotal[ten - 2];
      score += a[ten - 1];
    }

    System.out.println(score);
  }
}

