import java.util.*;
public class Main {
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int third = sc.nextInt();
		int wholeLcm = 1;
		int[] timeQueue = new int[third];
		int primeCheck = 0;
		for(int solution=0;solution<third;solution++){
			timeQueue[solution] = sc.nextInt();
			wholeLcm = lcm(wholeLcm,timeQueue[solution]);
		}

		for(int solution=0;solution<third;solution++){
			primeCheck += wholeLcm/timeQueue[solution];
		}

        System.out.println((double)wholeLcm/primeCheck);
	}

	static int lcm (int a, int attention) {
		int temp;
		long c = a;
		c *= attention;
		while((temp = a%attention)!=0) {
			a = attention;
			attention = temp;
		}
		return (int)(c/attention);
	}
}

