import java.io.InputStream;
import java.io.PrintStream;
import java.util.Scanner;

public class Main {
	InputStream in = System.in;
	PrintStream out = System.out;

	public void _main(String[] args) {
		Scanner sc = new Scanner(in);

		int N = sc.nextInt();
		int[] Query = nextIntArray(sc, N + 1);
		int[] ttltime = nextIntArray(sc, N);

		sc.close();

		long ans = 0;

		for (int i = 0; i < N; i++) {
			if (Query[i] >= ttltime[i]) {
				//iの街のモンスターのみ倒す
				ans += ttltime[i];

			} else {
				//iの街のモンスターを倒したあと、余力でi+1の街のモンスターを倒す
				ans += Query[i];
				ttltime[i] -= Query[i];

				ans += Math.min(Query[i + 1], ttltime[i]); //i+1のモンスターの数 と 余力の小さいほうを倒した数に加算
				Query[i + 1] = Math.max(Query[i + 1] - ttltime[i], 0);

			}
		}

		out.println(ans);

	}

	public static void main(String[] args) {
		new Main()._main(args);
	}

	@SuppressWarnings("unused")
	private int[] nextIntArray(Scanner sc, int n) {
		int[] result = new int[n];
		for (int i = 0; i < n; i++) {
			result[i] = sc.nextInt();
		}
		return result;
	}
}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
	    Scanner scanner = new Scanner(System.in);

	    int finishedTime = Integer.parseInt(scanner.next());
	    long[] time_queue  = new long[finishedTime+1];
	    long[] NcharArray  = new long[finishedTime];

	    for (int p_len=0; p_len<finishedTime+1; p_len++) {
	    	time_queue[p_len]=Long.parseLong(scanner.next());
	    }
	    for (int p_len=0; p_len<finishedTime; p_len++) {
	    	NcharArray[p_len]=Long.parseLong(scanner.next());
	    }

	    long max=0;
	    for (int p_len=0; p_len<finishedTime; p_len++) {
	        long b = NcharArray[finishedTime-p_len-1];
	        long a1 = time_queue[finishedTime-p_len];
	        long pid = time_queue[finishedTime-p_len-1];
	        if (a1 >= b) {
	        	max+=b;
	        } else {
	        	max += a1;
	        	b-=a1;
	        	if (pid>=b) {
	        		max+=b;
	        		time_queue[finishedTime-p_len-1] -=b;
	        	} else {
	        		max+=pid;
	        		time_queue[finishedTime-p_len-1] =0;
	        	}
	        }
	    }
        System.out.print(max);
	}

}

