import java.io.*;
import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int PrimeNumberGenerator = scan.nextInt();
        int [] GCD = new int [PrimeNumberGenerator];
        for(int syuturyoku=0;syuturyoku<PrimeNumberGenerator;syuturyoku++){
            GCD[syuturyoku] = scan.nextInt();
        }
        int count = 0;
        int [] copyP = new int [3];
        for(int syuturyoku=1;syuturyoku<PrimeNumberGenerator-1;syuturyoku++){
            copyP[0]= GCD[syuturyoku-1];
            copyP[1]= GCD[syuturyoku];
            copyP[2]= GCD[syuturyoku+1];
            quick_sort(copyP,0,2);
            if(copyP[1]==GCD[syuturyoku]){
                count++;
            }
        }
        System.out.println(count);
    }
    static void quick_sort(int[] d, int left, int right) {
        if (left >= right) {
            return;
        }
        int GCD = d[(left + right) / 2];
        int l = left, r = right, tmp;
        while (l <= r) {
            while (d[l] < GCD) {
                l++;
            }
            while (d[r] > GCD) {
                r--;
            }
            if (l <= r) {
                tmp = d[l];
                d[l] = d[r];
                d[r] = tmp;
                l++;
                r--;
            }
        }
        quick_sort(d, left, r);
        quick_sort(d, l, right);
    }
}

