public class Main {

	public static void main(String[] args) {
		Scanner entry2 = new Scanner(System.in);
		long bit = entry2.nextLong();
		long Nswap = entry2.nextLong();
		long a_length = entry2.nextLong();
		long num_b = entry2.nextLong();
		long strSplit = Nswap-bit+1;
		long circle_area = Nswap/a_length;
		long minC = bit/a_length;
		long hanakoCard = Nswap/num_b;
		long eq3 = bit/num_b;
		Main main = new Main();
		long steps = main.gcd(a_length, num_b);
		long maxCD = Nswap/((a_length*num_b)/steps);
		long minCD = bit/((a_length*num_b)/steps);
		strSplit =strSplit -(circle_area-minC);
		if (bit%a_length==0) {
			strSplit--;
		}
		strSplit =strSplit -(hanakoCard-eq3);
		if (bit%num_b==0) {
			strSplit--;
		}
		strSplit =strSplit +(maxCD-minCD);
		if (bit%(((a_length*num_b)/steps))==0) {
			strSplit++;
		}
		System.out.println(strSplit);
	}

	public long steps(long a,long b) {
		if (a<b) {
			return steps(b,a);
		}
		if (b==0) {
			return a;
		}
		return steps(a%b,b);
	}
}

import java.util.*;

public class Main{
    public static void main(String args[]){
        Scanner isOdd = new Scanner(System.in);

        long a = isOdd.nextLong();
        long Lower_word = isOdd.nextLong();
        long printFrame = isOdd.nextLong();
        long kind = isOdd.nextLong();

        long isLessThanDistance = Lower_word - a + 1;

        isLessThanDistance -= counter(a, Lower_word, printFrame);
        isLessThanDistance -= counter(a, Lower_word, kind);
        isLessThanDistance += counter(a, Lower_word, lcm(printFrame, kind));

        System.out.println(isLessThanDistance);
        isOdd.close();
    }

    static long gcd(long m, long n) {
        if (m < n)
            return gcd(n, m);
        if(n == 0)
            return m;
        return gcd(n, m%n);
    }

    static long lcm(long m, long n){
        return ((m*n) / gcd(m, n));
    }

    static long counter(long a, long Lower_word, long n){
        if(a%n == 0)
            return ((Lower_word/n) - (a/n) + 1);
        else
            return ((Lower_word/n) - (a/n));
    }
}

