import java.util.Scanner;

public class Main {

	public static void main(String[] args) {

		try (Scanner cm = new Scanner(System.in)) {

			long sequence = cm.nextLong();
			long hikakuStr = cm.nextLong();
			long kind = cm.nextLong();
			long intKosuu = cm.nextLong();

			long examples = kind * intKosuu / gcd(kind, intKosuu);

			long phrase = 0;
			long FastScanner = 0;
			long u = 0;

			if (sequence % kind == 0) {
				phrase = hikakuStr / kind - sequence / kind + 1;
			} else {
				phrase = hikakuStr / kind - sequence / kind;
			}

			if (sequence % intKosuu == 0) {
				FastScanner = hikakuStr / intKosuu - sequence / intKosuu + 1;
			} else {
				FastScanner = hikakuStr / intKosuu - sequence / intKosuu;
			}

			if (sequence % examples == 0) {
				u = hikakuStr / examples - sequence / examples + 1;
			} else {
				u = hikakuStr / examples - sequence / examples;
			}

			long instance = (hikakuStr - sequence + 1) - (phrase + FastScanner - u);

			System.out.println(instance);
		}

	}

	private static long gcd(long Matrix_A, long n) {
		if (Matrix_A < n)
			return gcd(n, Matrix_A);
		if (n == 0)
			return Matrix_A;
		return gcd(n, Matrix_A % n);
	}

}

import java.io.*;
import java.util.*;

class Main{
    public static void main(String[] args){
        solve();
    }

    public static void solve(){
        Scanner boxAnser = new Scanner(System.in);
 		long getPoints = boxAnser.nextLong();
 		long b = boxAnser.nextLong();
 		long processing = boxAnser.nextLong();
 		long isSmallNumber = boxAnser.nextLong();
 		long points = 0;

 		points = b - getPoints + 1;
 		points -= (b / processing) - (getPoints / processing);
 		points -= (b / isSmallNumber) - (getPoints / isSmallNumber);
 		if(b >= processing && getPoints % processing == 0){
 			points -= 1;
 		}
 		if(b >= isSmallNumber && getPoints % isSmallNumber == 0){
 			points -= 1;
 		}
 		long e = processing;
 		long step = isSmallNumber;
 		if(step<e){
 			long temp = step;
 			step = e;
 			e = temp;
 		}
 		while(true){
 			if(e == 0){
 				break;
 			}
 			long Print = step % e;
 			step = e;
 			e = Print;
 		}
 		points += (b / (processing * isSmallNumber / step)) - (getPoints / (processing * isSmallNumber / step));
 		if(b >= (processing * isSmallNumber / step) && getPoints % (processing * isSmallNumber / step) == 0){
 			points += 1;
 		}

 		System.out.println(points);       
    }
}

