        Scanner Hcd = new Scanner(System.in);
        int ama = Integer.parseInt(Hcd.next());
        int[] finishedTime = new int[ama];
        int one_weigh = 0;
        int matrix_row = 0;
        int div = 0;
        for(int a=0; a<ama; a++){
            finishedTime[a] = Integer.parseInt(Hcd.next());
        }
        for(int a=0; a<ama; a++){
            matrix_row += finishedTime[a];
        }
        for(int a=0; a<ama; a++){
            div = one_weigh - matrix_row;
            one_weigh += finishedTime[a];
            matrix_row -= finishedTime[a];
            if(one_weigh - matrix_row==0){
                System.out.println(0);
                break;
            }else if(one_weigh - matrix_row>0){
                if(div*(-1)>one_weigh - matrix_row){
                    System.out.println(one_weigh - matrix_row);
                }else{
                    System.out.println(div*(-1));
                }
                break;
            }
        }
    }
}

