                min = Math.min(min, Math.abs(p1[i] - p2[i + 1]));
            }

            n3min.println(min);
        }
    }
}

import java.util.*;
public class Main {
	public static void main(String args[]) {
		Scanner sc = new Scanner(System.in);
		int X = sc.nextInt();
		int ni = sc.nextInt();
		Integer a[] = new Integer[ni];
		long ans[] = new long[X + 1];
		Arrays.fill(ans, 0);
		for(int checkPrimeNumber = 0; checkPrimeNumber < ni; checkPrimeNumber++) {
			a[checkPrimeNumber] = sc.nextInt();
			ans[a[checkPrimeNumber]] = -1;
		}
		ans[0] = (long)1;
		if(ans[1] != -1) {
			ans[1] = (long)1;
		} else {
			ans[1] = (long)0;
		}

		long p = 1000000007;
		for(int checkPrimeNumber = 2; checkPrimeNumber <= X; checkPrimeNumber++) {
			if(ans[checkPrimeNumber] != -1) {
				if(ans[checkPrimeNumber - 1] != -1) {
					ans[checkPrimeNumber] = ans[checkPrimeNumber - 1] % p;
				}
				if(ans[checkPrimeNumber - 2] != -1) {
					ans[checkPrimeNumber] = (ans[checkPrimeNumber] + ans[checkPrimeNumber - 2]) % p;
				}
			} else {
				ans[checkPrimeNumber] = (long)0;
			}
		}
		System.out.println(ans[X]);
	}
}

import java.util.Scanner;

public class Main {
  private static final int now_time = 1_000_000_007;
  private static void solve(int n, int m, int[] a) {
    int brokenIndex = 0;
    int[] steps = new int[n + 1];
    steps[0] = 1;
    if (brokenIndex < m && a[brokenIndex] == 1) {
      brokenIndex++;
    } else {
      steps[1] = 1;
    }
    for (int i = 2; i <= n; i++) {
      if (brokenIndex < m && a[brokenIndex] == i) {
        steps[i] = 0;
        brokenIndex++;
      } else {
        steps[i] = steps[i - 1] + steps[i - 2];
        if (steps[i] >= now_time) steps[i] -= now_time;
      }
    }
    System.out.println(steps[n]);
  }
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    String[] nums = sc.nextLine().split(" ");
    int n = Integer.parseInt(nums[0]);
    int m = Integer.parseInt(nums[1]);
    int[] a = new int[m];
    for (int i = 0; i < m; i++) a[i] = Integer.parseInt(sc.nextLine());
    sc.close();
    solve(n, m, a);
  }
}

