        charStr[0] = 1;
        charStr[1] = 1;
        int numList = 1000000007;
        for (int score2=2;score2<=xToSecondPower;score2++){
            charStr[score2] = 0;
            if (bool[score2-2])charStr[score2]+=charStr[score2-2];
            if (bool[score2-1])charStr[score2]+=charStr[score2-1];
            charStr[score2] %= numList;

        }
        System.out.println(charStr[xToSecondPower]);
    }
}

