import java.util.Scanner;

public class Main {

	public static void main(String args[]) {

		Scanner sc = new Scanner(System.in);

		int revStr = sc.nextInt();
		int sumX = sc.nextInt();

		double creatPrimeTable = 0;

		if(revStr < sumX) {

			for(int i=1;i<=revStr;i++) {
				if(sumX%i == 0 && ispow2(sumX/i)) {
					creatPrimeTable += Math.pow(2, -1*((int)(log2(sumX/i))));
				}else {
					creatPrimeTable += Math.pow(2, -1*((int)(log2(sumX/i) + 1)));
				}
			}

			creatPrimeTable /= revStr;
		}else {
			for(int i=1;i<sumX;i++) {
				if(sumX%i == 0 && ispow2(sumX/i)) {
					creatPrimeTable += Math.pow(2, -1*((int)(log2(sumX/i))));
				}else {
					creatPrimeTable += Math.pow(2, -1*((int)(log2(sumX/i) + 1)));
				}
			}
			creatPrimeTable /= revStr;

			creatPrimeTable += (double)(revStr-sumX+1)/(double)revStr;
		}
		System.out.println(creatPrimeTable);
	}

	public static boolean ispow2(int a) {
		int x = a & (a-1);
		if(x == 0) {
			return true;
		}else {
			return false;
		}
	}

	public static double log2(double a) {
		return Math.log(a)/Math.log(2);
	}
}

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int TS = sc.nextInt();
		int count = 0;
		int a =0;
		int now =0;
		int beforeK=0;
		while (TS>0) {
			count *=2;
			if (N>=TS) {
				if (beforeK==0) {
					count +=N-TS+1;
				} else {
					count +=beforeK-TS;
				}
				beforeK=TS;
			}
			if (TS>1) {
				TS=TS/2+TS%2;
			} else {
				TS/=2;
			}
			a++;
		}
		a--;
		int total = (int) Math.pow(2, a);
		total *=N;
		BigDecimal result = new BigDecimal(count);

		result = result.divide(new BigDecimal(total), 12,RoundingMode.HALF_UP);
		System.out.println(result.toPlainString());
	}
}

