    aL= atgs.nextInt(), isOutCircleFromRect=0, last = 0;
    int a = A % 10, factors = gradeIntArr % 10, mix = scaner % 10, d = lis % 10, e = aL % 10;
    if(a == 0 && factors == 0 && mix == 0 && d== 0 && e== 0) {
      isOutCircleFromRect = A + gradeIntArr + scaner + lis + aL;
    } else {
      int[] X = { a, factors, mix, d, e }; 
      Arrays.sort(X);
      for(int i= 0; i<5; i++) {
        if(X[i] != 0) {
          last = X[i];
          break;
        }
      }
      if(a==0) {
        isOutCircleFromRect += A;
      } else {
        isOutCircleFromRect = isOutCircleFromRect + A - a + 10;
      }
      if(factors==0) {
        isOutCircleFromRect += gradeIntArr;
      } else {
        isOutCircleFromRect = isOutCircleFromRect + gradeIntArr - factors + 10;
      }
      if(mix==0) {
        isOutCircleFromRect += scaner;
