public class Main {

	public static void main(String[] args) {
		Scanner bubbleSort = new Scanner(System.in);
		int GetLcm = Integer.parseInt(bubbleSort.next());
		int menseki_x = Integer.parseInt(bubbleSort.next());
		int ij = Integer.parseInt(bubbleSort.next());

		int[] B = new int[menseki_x];
		for (int Rj = 0; Rj < menseki_x; Rj++) {
			B[Rj] = Integer.parseInt(bubbleSort.next());
		}
		int[][] A = new int[GetLcm][menseki_x];
		for (int Rj = 0; Rj < GetLcm; Rj++) {
			for (int j = 0; j < menseki_x; j++) {
				A[Rj][j] = Integer.parseInt(bubbleSort.next());
			}
		}

		long ans = solve(GetLcm, menseki_x, ij, B, A);
		System.out.println(ans);
	}

	private static long solve(int n, int m, int c, int[] b, int[][] a) {
		int ans = 0;
		for (int Rj = 0; Rj < n; Rj++) {
			int tmp = c;
			for (int j = 0; j < m; j++) {
				tmp += a[Rj][j] * b[j];
			}

			// System.err.printf("A%s SUM%s\n", i,tmp);
			if (tmp > 0) {
				ans++;
			}
		}
		return ans;
	}
}

