import java.util.Scanner;
import java.util.ArrayDeque;

public class Main {
  public static void main (String[] args) {
    Scanner in = new Scanner(System.in);

    while (in.hasNext()) {
      String K = in.next();
      ArrayDeque<Character> gcd_euclid = new ArrayDeque<Character>();

      for (int totalPointTaro = 0; totalPointTaro < K.length(); ++totalPointTaro) {
        char strMessage = K.charAt(totalPointTaro);
        if (gcd_euclid.isEmpty()) {
          gcd_euclid.push(strMessage);
        } else if (strMessage == '1' && gcd_euclid.peek() == '0') {
          gcd_euclid.pop();
        } else if (strMessage == '0' && gcd_euclid.peek() == '1') {
          gcd_euclid.pop();
        } else {
          gcd_euclid.push(strMessage);
        }
      }

      System.out.println(K.length() - gcd_euclid.size());
    }
  }
}

