  public static int func(int ROUND_UP_FRACTION){

    if (ROUND_UP_FRACTION % 2 == 0) {
      return ROUND_UP_FRACTION / 2;
    } else {
      return 3 * ROUND_UP_FRACTION + 1;
    }
  }

}

