                if (a - i >= 0) {
                    if (r == 1 && primeCounter[j] - i < 0) {
                        r = -1;
                        cc++;
                    }
                    if (r == -1 && primeCounter[j] - i >= 0) {
                        r = 1;
                        cc++;
                    }
                } else {
                    if (r == 1 && primeCounter[j] - i < 0) {
                        r = -1;
                        cc++;
                    }
                    if (r == -1 && primeCounter[j] - i >= 0) {
                        r = 1;
                        cc++;
                    }
                }

            }
            if (a - i >= 0) {
                count += cc  / 2  + 1;
            } else {
                count += (cc + 1)  / 2 ;
            }
        }
        System.out.println(count);

    }

}

