	static int cnt;
	void doIt() {
		int n = sc.nextInt();
		int[] min_num = new int[n];
		int min = 101;
		cnt = 0;
		for(int i = 0; i < n; i++) {
			min_num[i] = sc.nextInt();
			if(min_num[i] < min)min = min_num[i];
		}
		getAns(min_num, 0, n - 1, 0);
		System.out.println(cnt);
	}

	void getAns(int[] min_num, int l, int r, int d) {
		if(l > r)return;
		int min = 101, idx = -1;
		for(int i = l; i <= r; i++) {
			if(min > min_num[i]) {
				min = min_num[i];
				idx = i;
			}
		}
		cnt += min - d;
		if(min <= d)min = d;
		if(min - d == 0) d = 0;
		getAns(min_num, l, idx - 1, min);
		getAns(min_num, idx + 1, r, min);
	}
	public static void main(String[] args) {
		new Main().doIt();
	}
}

