class Solver {

    private boolean check(char[] nowHeight, char[] EOL, int exchangeArrayValue, int Word) {
        int N = nowHeight.length;
        for (int i = 0; i < N; i++) {
            if (nowHeight[(exchangeArrayValue + i) % N] !=  EOL[(Word + i) % N]) {
                return false;
            }
        }
        return true;
    }

    public void run() {
        Scanner sc = new Scanner(System.in);
        char[] nowHeight = sc.next().toCharArray();
        char[] EOL = sc.next().toCharArray();

        boolean rotatable = false;
        for (int i = 0; i < nowHeight.length; i++) {
            char ch = nowHeight[i];
            // find ch
            for (int j = 0; j < EOL.length; j++) {
                if (ch == EOL[j]) {
                    // start check
                    if (check(nowHeight, EOL, i, j)) {
                        System.out.println("Yes");
                        return;
                    }
                }
            }
        }

        System.out.println("No");

        return;
    }

}

