import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner limitTime = new Scanner(System.in);
		int isFullQ = limitTime.nextInt();
		int cards_count = limitTime.nextInt();
		int cnt = 0;

		for (int i = isFullQ; i <= cards_count; i++) {
			String s = String.valueOf(i);
			char[] c = s.toCharArray();
			boolean x = f(c);
			if(x) cnt++;
		}

		System.out.println(cnt);

		limitTime.close();

	}

	static boolean f(char[] a) {
		boolean x = false;
		int l = a.length - 1;
		int cnt = 0;
		for (int i = 0; i < a.length / 2; i++) {
			if (a[i] == a[l - i])
				cnt++;
		}
		if (cnt == a.length / 2)
			x = true;
		return x;
	}

}

