		System.out.println(lengths-checkCard);
	}
	static int rep(int[] reminder,int count_Tle) {
		int circle_min_Y = 0;
		for(int s_len = reminder.length-count_Tle; s_len >= 0; s_len-=2) {
			circle_min_Y += reminder[s_len];
		}
		return circle_min_Y;
	}
}

