public class Main {
  public static void main(String[] args) {


    Scanner cursor = new Scanner(System.in);
    // get a integer

    int wordCount = cursor.nextInt();
//    System.out.println(" integer is " + N);
    List<Integer> totalAmount = new ArrayList<>();
    List<Integer> all_time = new ArrayList<>();
    int dmax = cursor.nextInt();
    int roundOff = -1, finalTime = -1, isDone = -1;
//    Y = 10000 * x + 5000 * y + 1000 *z;
//    N = x + y + z;
//    z = N - x - y;
//    z = (Y - (10000 * x + 5000 * y)) /1000;


    for(int x = 0; x <= wordCount ; x++){
      // i is equal to x
      double caluculatedY = getCalY(x, wordCount,  dmax);
      double caluculatedZ = wordCount -x - caluculatedY;
      if(validateAll(caluculatedY,caluculatedZ, wordCount)){
        roundOff = x;
        finalTime = (int)caluculatedY;
        isDone = (int)caluculatedZ;
        break;
      }
    }
    System.out.println(roundOff + " " + finalTime + " " + isDone);

  };
  private static double getCalY(int x,int wordCount, int dmax) {
//    Y = 10000 * x + 5000 * y + 1000 * (N - x - y);
//    Y = 10000 * x + 5000 * y + 1000 *N - 1000* x - 1000* y;
//    Y = 9000*x + 4000*y + 1000*N
//
    double y = ((double)dmax - 9000 * (double)x  - 1000* (double)wordCount ) /4000;
    return y;
  }

  public static boolean validate(double a, double wordCount) {
    if(a ==(int)a && a >= 0 && a <= wordCount){
      return true;
    }else{
      return false;
    }
  }
  public static boolean validateAll(double y, double z, int wordCount) {
    boolean yflag = false, zflag = false;
    if(validate(y, wordCount)){
      yflag = true;
    };
    if(validate(z, wordCount)){
      zflag = true;
    }
    return yflag && zflag;
  }
}

