		for(int push =1;push <= n;push++) {
			int digitSum = calcDigitSum(push);
			if(digitSum >= setX && digitSum <= getFormattedTime) {
				answer+= push;
			}
		}
		System.out.println(answer);
	}

	private static int calcDigitSum(int push) {
		String[] digitArray = String.valueOf(push).split("");
		int result = 0;
		for(String digit : digitArray) {
			result += Integer.parseInt(digit);
		}
		return result;
	}
}

