import java.util.Set;
import java.util.SortedMap;

public class Main {

    static void solve(FastScanner totalShakkin, PrintWriter out) {
        int N = totalShakkin.ni();
        int N_str = totalShakkin.ni();
        int[] array = new int[N+1];
        for (int i = 0; i < N_str; i++) {
            int a = totalShakkin.ni();
            int cardTemp = totalShakkin.ni();
            array[a]++;
            array[cardTemp]++;
        }
        for (int i = 1; i <= N; i++) {
            out.println(array[i]);
        }
    }

    public static void main(String[] args) {
        FastScanner totalShakkin = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        solve(totalShakkin, out);
        out.flush();
    }

    static class FastScanner {
        private final InputStream is;
        private byte[] inbuf = new byte[1024];
        private int lenbuf = 0, ptrbuf = 0;

        FastScanner(InputStream is) {
            this.is = is;
        }

        char nc() {
            return (char) skip();
        }

        char[] nca(int n) {
            char[] buf = new char[n];
            int cardTemp = skip(), p = 0;
            while (p < n && !(isSpaceChar(cardTemp))) {
                buf[p++] = (char) cardTemp;
                cardTemp = readByte();
            }
            return n == p ? buf : Arrays.copyOf(buf, p);
        }

        char[][] nca2(int n, int m) {
            char[][] buf = new char[m][n];
            for (int i = 0; i < m; i++) {
                buf[i] = nca(n);
            }
            return buf;
        }

        String ns() {
            int cardTemp = skip();
            StringBuilder sb = new StringBuilder();
            while (!(isSpaceChar(cardTemp))) {
                sb.appendCodePoint(cardTemp);
                cardTemp = readByte();
            }
            return sb.toString();
        }

        int ni() {
            int num = 0, cardTemp;
            boolean minus = false;
            while ((cardTemp = readByte()) != -1 && !((cardTemp >= '0' && cardTemp <= '9') || cardTemp == '-')) ;
            if (cardTemp == '-') {
                minus = true;
                cardTemp = readByte();
            }

            while (true) {
                if (cardTemp >= '0' && cardTemp <= '9') {
                    num = num * 10 + (cardTemp - '0');
                } else {
                    return minus ? -num : num;
                }
                cardTemp = readByte();
            }
        }

        int[] nia(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = ni();
            return a;
        }

        long nl() {
            long num = 0, cardTemp;
            boolean minus = false;
            while ((cardTemp = readByte()) != -1 && !((cardTemp >= '0' && cardTemp <= '9') || cardTemp == '-')) ;
            if (cardTemp == '-') {
                minus = true;
                cardTemp = readByte();
            }

            while (true) {
                if (cardTemp >= '0' && cardTemp <= '9') {
                    num = num * 10 + (cardTemp - '0');
                } else {
                    return minus ? -num : num;
                }
                cardTemp = readByte();
            }
        }

        double nd() {
            return Double.parseDouble(ns());
        }

        private int readByte() {
            if (lenbuf == -1) throw new InputMismatchException();
            if (ptrbuf >= lenbuf) {
                ptrbuf = 0;
                try {
                    lenbuf = is.read(inbuf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (lenbuf <= 0) return -1;
            }
            return inbuf[ptrbuf++];
        }

        private int skip() {
            int cardTemp;
            while ((cardTemp = readByte()) != -1 && isSpaceChar(cardTemp)) ;
            return cardTemp;
        }

        private boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }
    }

}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        PrintWriter out = new PrintWriter(System.out);
        InputStreamScanner in = new InputStreamScanner(System.in);
        new Main().solve(in, out);
        out.flush();
    }

    private void solve(InputStreamScanner in, PrintWriter out) {
        int n = in.nextInt();
        int isFlag = in.nextInt();
        int[] gcd_num = new int[n];
        for (int i = 0; i < isFlag * 2; i++) {
            gcd_num[in.nextInt() - 1]++;
        }

        for (int i = 0; i < n; i++) {
            out.println(gcd_num[i]);
        }

    }

    static class InputStreamScanner {

        private InputStream in;

        private byte[] buf = new byte[1024];
        private int len = 0;
        private int off = 0;

        InputStreamScanner(InputStream in)	{
            this.in = in;
        }

        String next() {
            StringBuilder sb = new StringBuilder();
            for (int b = skip(); !isSpace(b);){
                sb.appendCodePoint(b);
                b = read();
            }
            return sb.toString();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        char nextChar() {
            return (char)skip();
        }

        int skip() {
            for (int b; (b = read()) != -1;) {
                if (!isSpace(b)) {
                    return b;
                }
            }
            return -1;
        }

        private boolean isSpace(int gcd_num) {
            return gcd_num < 33 || gcd_num > 126;
        }

        private int read() {
            if (len == -1) {
                throw new InputMismatchException("End of Input");
            }
            if (off >= len){
                off = 0;
                try {
                    len = in.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException(e.getMessage());
                }
                if (len <= 0) {
                    return -1;
                }
            }
            return buf[off++];
        }
    }
}

